def _get_audit(self, parts, operator: str) -> None:
    tenant_id = self._audit_tenant(parts)
    if tenant_id is None:
        return
    qs = parse_qs(parts.query, keep_blank_values=True)

    since = None
    until = None
    values, errored = self._single_param(qs, "since")
    if errored:
        return
    if values:
        since = values[0]
        try:
            since = audit_mod.canonical_rfc3339(since)
        except ValueError:
            self._bad_request(
                "field since must be an RFC3339 timestamp"
            )
            return
    values, errored = self._single_param(qs, "until")
    if errored:
        return
    if values:
        until = values[0]
        try:
            until = audit_mod.canonical_rfc3339(until)
        except ValueError:
            self._bad_request(
                "field until must be an RFC3339 timestamp"
            )
            return
    if since is not None and until is not None and since > until:
        self._bad_request(
            "field until must not be earlier than since"
        )
        return

    values, errored = self._single_param(qs, "key_id")
    if errored:
        return
    key_id = values[0] if values else None
    if key_id is not None and not is_valid_key_id(key_id):
        # An illegal identifier is a tenant_conflict event, like any
        # other malformed tenant/key parameter.
        if self._record_conflict():
            self._bad_request("field key_id must be a UUID4")
        return

    values, errored = self._single_param(qs, "action")
    if errored:
        return
    action = values[0] if values else None
    if action is not None and action not in audit_mod.ACTIONS:
        self._bad_request(
            "field action must be one of: %s"
            % ", ".join(audit_mod.ACTIONS)
        )
        return

    values, errored = self._single_param(qs, "operation_id")
    if errored:
        return
    operation_id = values[0] if values else None
    if operation_id is not None and not is_valid_key_id(
        operation_id
    ):
        # An empty, duplicated or malformed operation_id is a plain
        # parameter 400 naming the field: it precedes the policy check
        # and writes no audit event (only a missing/conflicting
        # tenant source records tenant_conflict).
        self._bad_request("field operation_id must be a UUID4")
        return

    limit = 100
    values, errored = self._single_param(qs, "limit")
    if errored:
        return
    if values:
        raw_limit = values[0]
        if not _POSITIVE_INT_RE.fullmatch(raw_limit):
            self._bad_request(
                "field limit must be an integer between 1 and 1000"
            )
            return
        limit = int(raw_limit)
        if not 1 <= limit <= 1000:
            self._bad_request(
                "field limit must be an integer between 1 and 1000"
            )
            return

    values, errored = self._single_param(qs, "cursor")
    if errored:
        return
    cursor = values[0] if values else None

    # Parameter validation (400) precedes authorization; a policy
    # rejection of an audit query is recorded with the original
    # action ("audit") and outcome rejected, key_id null.
    if not self._enforce(
        tenant_id, None, audit_mod.ACTION_AUDIT, operator
    ):
        return

    try:
        page = store.audit.query(
            tenant_id,
            key_id=key_id,
            action=action,
            operation_id=operation_id,
            since=since,
            until=until,
            limit=limit,
            cursor=cursor,
        )
    except InvalidCursor:
        self._bad_request("invalid or expired cursor")
        return
    self._send_json(
        200,
        {
            "events": [e.to_response() for e in page.events],
            "next_cursor": page.next_cursor,
        },
    )

def _empty_request_body(self) -> bool:
    """Validate a GET body as absent or an empty JSON object."""
    try:
        length = int(self.headers.get("Content-Length", 0))
    except ValueError:
        self._bad_request("invalid Content-Length")
        return False
    raw = self.rfile.read(length) if length > 0 else b""
    if not raw:
        return True
    try:
        payload = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        self._bad_request("request body must be valid JSON")
        return False
    if not isinstance(payload, dict):
        self._bad_request("request body must be a JSON object")
        return False
    if payload:
        extra = next(iter(payload))
        self._bad_request(
            "field %s is not accepted by this endpoint" % extra
        )
        return False
    return True

def _get_audit_verify(self, parts, operator: str) -> None:
    tenant_id = self._audit_tenant(parts)
    if tenant_id is None:
        return
    if not self._empty_request_body():
        return
    if not self._enforce(
        tenant_id, None, audit_mod.ACTION_AUDIT, operator
    ):
        return
    self._send_json(200, store.audit.verify(tenant_id))

